//! Write spacing of the original `dl` driver inside a tick, per driver build (colour clocks),
//! measured from the reference's register-write logs (gaps between consecutive writes by kind and
//! voice, medians over the ticks of each corpus file; start gaps from the tick entry). Generated data.

/// One module build: the row key (hunk longs, init, play, stop offsets), the gap before the first
/// write of a tick by write key, the gap before a write by its key whatever came before, and the
/// gap by (previous key, key).
pub struct GapSet {
    pub key: (u32, u32, u32, u32),
    /// The DMA start writes carry the master enable bit.
    pub master: bool,
    pub start: &'static [(u8, u16)],
    pub first: &'static [(u8, u16)],
    pub any: &'static [(u8, u16)],
    pub pairs: &'static [(u8, u8, u16)],
}

/// The shift of the start gaps: the tick entry is that many colour clocks earlier than the
/// reference's, so that no start gap is negative.
pub const START_SHIFT: u64 = 420;

